// Shared helpers for the DSP unit tests: golden-file loading (generated by
// tool/oracle/run_oracle.sh from the real SDR++ headers), comparisons, tone analysis and
// chunked processing.
import 'dart:io';
import 'dart:math' as math;
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:sdr_flutter/sdrpp/dsp/processor.dart';

final String goldenDir = '${Directory.current.path}/test/sdrpp/dsp/golden';

/// Loads a golden float32 dump.
Float32List golden(String name) {
  final f = File('$goldenDir/$name.f32');
  if (!f.existsSync()) {
    fail('Golden $name missing: run tool/oracle/run_oracle.sh');
  }
  final bytes = f.readAsBytesSync();
  return Float32List.view(Uint8List.fromList(bytes).buffer, 0, bytes.length ~/ 4);
}

/// Max |a−b| over the first [n] floats (default: min length).
double maxAbsDiff(Float32List a, Float32List b, [int? n]) {
  final len = n ?? math.min(a.length, b.length);
  double m = 0;
  for (int i = 0; i < len; i++) {
    final d = (a[i] - b[i]).abs();
    if (d > m || d.isNaN) m = d.isNaN ? double.infinity : d;
  }
  return m;
}

/// Max |x| over the first [n] floats.
double maxAbs(Float32List a, [int? n]) {
  final len = n ?? a.length;
  double m = 0;
  for (int i = 0; i < len; i++) {
    m = math.max(m, a[i].abs());
  }
  return m;
}

/// Asserts that [actual] matches [expected] (first [n] floats) within [tol] relative to the
/// reference peak (tol·max(1, peak)).
void expectClose(Float32List actual, Float32List expected, {int? n, double tol = 1e-5, String? reason}) {
  final len = n ?? expected.length;
  expect(actual.length, greaterThanOrEqualTo(len), reason: '${reason ?? ''} length');
  final peak = math.max(1.0, maxAbs(expected, len));
  final d = maxAbsDiff(actual, expected, len);
  expect(d, lessThanOrEqualTo(tol * peak), reason: '${reason ?? ''} max diff $d (peak $peak)');
}

/// Runs [p] over [input] ([count] samples) in chunks produced by [chunker], collecting output.
/// [outFactor] bounds the output-to-input ratio for buffer sizing.
Float32List runChunked(Processor p, Float32List input, int count, List<int> chunks, {double outFactor = 1.0}) {
  final ist = p.inType.stride, ost = p.outType.stride;
  final res = <double>[];
  int pos = 0;
  int ci = 0;
  while (pos < count) {
    int c = chunks[ci++ % chunks.length];
    if (c > count - pos) c = count - pos;
    final inBuf = Float32List.sublistView(input, pos * ist, (pos + c) * ist);
    final outBuf = Float32List(((c * math.max(1.0, outFactor)).ceil() + 16) * math.max<int>(ist, ost) + 16);
    final n = p.process(c, Float32List.fromList(inBuf), outBuf);
    res.addAll(Float32List.sublistView(outBuf, 0, n * ost));
    pos += c;
  }
  return Float32List.fromList(res);
}

/// Deterministic random chunk sizes in [1, maxChunk].
List<int> randomChunks(int seed, int maxChunk, [int n = 257]) {
  final r = math.Random(seed);
  return List.generate(n, (_) => 1 + r.nextInt(maxChunk));
}

/// Amplitude of the component at [freq] (Hz) of a real signal (single-bin DFT, Hann window
/// compensated), over samples [start, end).
double toneAmplitude(Float32List x, double freq, double sr, {int start = 0, int? end, int stride = 1, int lane = 0}) {
  final e = end ?? (x.length ~/ stride);
  final n = e - start;
  double re = 0, im = 0, wsum = 0;
  for (int i = 0; i < n; i++) {
    final w = 0.5 - 0.5 * math.cos(2 * math.pi * i / n);
    final v = x[(start + i) * stride + lane] * w;
    final ph = 2 * math.pi * freq * i / sr;
    re += v * math.cos(ph);
    im -= v * math.sin(ph);
    wsum += w;
  }
  return 2 * math.sqrt(re * re + im * im) / wsum;
}

/// Frequency (Hz) of the strongest component of a real signal between [fMin] and [fMax],
/// scanned in [step] Hz increments.
double peakFrequency(Float32List x, double sr,
    {double fMin = 20, double fMax = 5000, double step = 10, int start = 0, int? end, int stride = 1, int lane = 0}) {
  double best = 0, bestF = fMin;
  for (double f = fMin; f <= fMax; f += step) {
    final a = toneAmplitude(x, f, sr, start: start, end: end, stride: stride, lane: lane);
    if (a > best) {
      best = a;
      bestF = f;
    }
  }
  return bestF;
}

/// Complex tone e^(j2πft/sr)·amp, [n] samples, interleaved.
Float32List complexTone(int n, double freq, double sr, {double amp = 1.0, double phase = 0}) {
  final out = Float32List(2 * n);
  for (int i = 0; i < n; i++) {
    final ph = 2 * math.pi * freq * i / sr + phase;
    out[2 * i] = amp * math.cos(ph);
    out[2 * i + 1] = amp * math.sin(ph);
  }
  return out;
}

/// Mean power of a complex (interleaved) signal over samples [start, end).
double complexPower(Float32List x, int start, int end) {
  double s = 0;
  for (int i = start; i < end; i++) {
    s += x[2 * i] * x[2 * i] + x[2 * i + 1] * x[2 * i + 1];
  }
  return s / (end - start);
}

/// Stride helper re-export.
int strideOf(SampleType t) => t.stride;
